sequence=""

def ori_finder(seq):
    """ Find ori from whole genome so that we can use the ori sequence to search for DNA A boxes, most freq kmers and its RC"""
    skew=[0] #initial skew set to zero before we start looking at sequence
    for i in range(len(seq)): 
        if seq[i]=="C":
            skew.append(skew[i]-1)
        elif seq[i]=="G":
            skew.append(skew[i]+1)
        else: 
            skew.append(skew[i])

    min_skew=min(skew) #minimum skew (G-C difference)

    return [pos for pos in range(len(seq)) if skew[pos+1]==min_skew]

print(*ori_finder(sequence)) #return position of minimum skew in 0-based indexing -> reflects transition from reverse half strand to forward half strand (G-C difference decreasing to increasing)(skew slope turning from negative to positive) -> ori